<script setup lang="ts">
import { nextTick } from 'vue'
import QuickCreatePlan from './QuickCreatePlan.vue'
import { serviceLabel } from '~/utils/after-sales-display'
const props=defineProps<{modelValue?:string[]}>()
const pendingName=ref<string|null>(null)
const selector=ref<HTMLElement|null>(null)
function openCreate(query:string){selector.value?.querySelector('button[aria-expanded="true"]')?.dispatchEvent(new MouseEvent('click',{bubbles:true}));pendingName.value=query.trim()}
function closeCreate(){pendingName.value=null;nextTick(()=>selector.value?.querySelector('button')?.focus())}
function created(plan:any){rows.value=[...rows.value.filter(row=>row.id!==plan.id),plan];emit('update:modelValue',[...new Set([...(props.modelValue||[]),plan.id])]);closeCreate()}
const emit=defineEmits<{'update:modelValue':[value:string[]]}>()
const scope=useCompanyScope(), rows=ref<any[]>([]), error=ref(''), unavailable=ref(false)
watch(()=>scope.companyId.value,()=>{pendingName.value=null})
async function load(){const company=scope.companyId.value;error.value='';try{const result:any=await scope.fetch('/api/after-sales/configurations',{query:{includeArchived:'true',includeIds:(props.modelValue||[]).join(',')}});if(company===scope.companyId.value){rows.value=result;unavailable.value=false}}catch(e:any){if(company===scope.companyId.value){rows.value=[];unavailable.value=e?.statusCode===503||e?.status===503;error.value=unavailable.value?'Coverage plans are not available for this store yet.':'Could not load after-sales configurations.'}}}
onMounted(load);watch(()=>scope.companyId.value,load);watch(()=>props.modelValue?.join(','),()=>{if((props.modelValue||[]).some(id=>!rows.value.some(r=>r.id===id)))void load()})
</script>
<template><section class="mb-5 space-y-3 rounded-lg border border-gray-200 p-4 dark:border-gray-700"><div><h3 class="text-sm font-semibold">Warranty, guarantee and maintenance</h3><p class="mt-1 text-xs text-gray-500 dark:text-gray-400">Each sold unit receives its own agreements. A client is required at sale.</p></div><UAlert v-if="error" role="alert" color="gray" variant="soft" :title="error"/><template v-if="!unavailable"><UFormGroup label="Linked plans"><div ref="selector"><USelectMenu :model-value="modelValue||[]" :options="rows.filter(r=>!r.archived||(modelValue||[]).includes(r.id)).map(r=>({value:r.id,label:serviceLabel(r.kind)+' - '+r.name+(r.archived?' (archived)':'')}))" multiple value-attribute="value" option-attribute="label" searchable placeholder="Select plans and coverage" @update:model-value="value=>emit('update:modelValue',value)"><template #option-empty="{query}"><UButton size="xs" variant="ghost" block icon="i-heroicons-plus" :label="`Create '${query}'`" :disabled="!query?.trim()" @pointerdown.prevent.stop @mousedown.prevent.stop @click.prevent.stop="openCreate(query)"/></template></USelectMenu></div></UFormGroup><div class="flex flex-wrap gap-1"><UBadge v-for="row in rows.filter(r=>(modelValue||[]).includes(r.id))" :key="row.id" color="gray" variant="subtle" size="xs">{{row.name}}</UBadge></div><div class="flex flex-wrap gap-2"><UButton v-for="kind in ['maintenance','warranty','guarantee']" :key="kind" :to="{path:'/after-sales/'+kind,query:{entryCompany:scope.companyId.value}}" target="_blank" color="gray" variant="link" size="xs" icon="i-heroicons-arrow-top-right-on-square" class="p-0">Manage {{kind}}</UButton></div></template><QuickCreatePlan v-if="pendingName!==null" :name="pendingName" @created="created" @close="closeCreate"/></section></template>
